using FinanSmart.Api.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace FinanSmart.Api.Data.Configurations;public class RefreshTokenConfiguration:IEntityTypeConfiguration<RefreshToken>{public void Configure(EntityTypeBuilder<RefreshToken>b){b.HasIndex(x=>x.TokenHash).IsUnique();b.HasOne(x=>x.User).WithMany(x=>x.RefreshTokens).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);}}
